package com.witchersbestiary.board;
import java.util.*;
import net.fabricmc.fabric.api.event.lifecycle.v1.*;
import net.minecraft.registry.*;
import net.minecraft.server.*;
import net.minecraft.server.world.ServerWorld;
import net.minecraft.structure.StructureStart;
import net.minecraft.util.math.*;
import net.minecraft.world.Heightmap;
/** Main-thread bounded loaded-only visit repair. Structure references are read without locate/chunk requests. */
public final class VisitedVillageBoards {
 private static final Map<MinecraftServer,LinkedHashMap<String,Job>> JOBS=new HashMap<>();
 private static boolean enabled=true;
 private static int playerCursor;
 private static final class Job {
  final ServerWorld world;final String key;final List<ChunkPos> chunks=new ArrayList<>();final Set<Long> scanned=new HashSet<>();int cursor,placement,lastTouched;
  Job(ServerWorld world,String key,StructureStart start){this.world=world;this.key=key;lastTouched=world.getServer().getTicks();var box=start.getBoundingBox();for(int x=box.getMinX()>>4;x<=box.getMaxX()>>4;x++)for(int z=box.getMinZ()>>4;z<=box.getMaxZ()>>4;z++)chunks.add(new ChunkPos(x,z));var center=start.getChildren().isEmpty()?box:start.getChildren().getFirst().getBoundingBox();int cx=(center.getMinX()+center.getMaxX())/2,cz=(center.getMinZ()+center.getMaxZ())/2;chunks.sort(Comparator.comparingDouble(p->p.getCenterAtY(0).getSquaredDistance(new BlockPos(cx,0,cz))));}
 }
 public static boolean supported(ServerWorld world,net.minecraft.world.gen.structure.Structure structure){var registry=world.getRegistryManager().get(RegistryKeys.STRUCTURE);var id=registry.getId(structure);return id!=null&&((id.getNamespace().equals("minecraft")&&Set.of("village_plains","village_desert","village_snowy","village_taiga","village_savanna").contains(id.getPath()))||registry.getEntry(structure).isIn(net.minecraft.registry.tag.TagKey.of(RegistryKeys.STRUCTURE,net.minecraft.util.Identifier.of("witchersbestiary","notice_board_villages"))));}
 public static BlockPos existingBoard(ServerWorld world,ChunkPos cp){var chunk=world.getChunkManager().getWorldChunk(cp.x,cp.z);if(chunk==null)return null;var sections=chunk.getSectionArray();for(int sectionIndex=0;sectionIndex<sections.length;sectionIndex++){var section=sections[sectionIndex];if(section==null||!section.hasAny(state->state.isOf(NoticeBoards.BLOCK)))continue;for(int x=0;x<16;x++)for(int y=0;y<16;y++)for(int z=0;z<16;z++){var state=section.getBlockState(x,y,z);if(state.isOf(NoticeBoards.BLOCK)){var at=new BlockPos(cp.getStartX()+x,world.getBottomY()+sectionIndex*16+y,cp.getStartZ()+z);return NoticeBoardBlock.root(at,state);}}}return null;}
 public static String offer(ServerWorld world,StructureStart start){var server=world.getServer();var ledger=VillageBoardLedger.get(server);if(ledger.readOnly()||!start.hasChildren()||!supported(world,start.getStructure()))return null;String key=world.getRegistryKey().getValue()+"/"+world.getRegistryManager().get(RegistryKeys.STRUCTURE).getId(start.getStructure())+"/"+start.getPos().toLong();var jobs=JOBS.computeIfAbsent(server,s->new LinkedHashMap<>());var queued=jobs.get(key);if(queued!=null){queued.lastTouched=server.getTicks();return key;}if(ledger.outcome(key)!=null||jobs.size()>=16)return key;var bounds=start.getBoundingBox();var center=start.getChildren().isEmpty()?bounds:start.getChildren().getFirst().getBoundingBox();var existing=existingBoard(world,new ChunkPos(new BlockPos((center.getMinX()+center.getMaxX())/2,0,(center.getMinZ()+center.getMaxZ())/2)));if(existing!=null){ledger.record(key,"PLACED: existing "+existing.toShortString());return key;}long size=(long)((bounds.getMaxX()>>4)-(bounds.getMinX()>>4)+1)*((bounds.getMaxZ()>>4)-(bounds.getMinZ()>>4)+1);if(size>256)ledger.record(key,"FAILED: village footprint exceeds256chunk safety cap");else jobs.put(key,new Job(world,key,start));return key;}
 private static void discover(MinecraftServer server){var players=server.getPlayerManager().getPlayerList();if(players.isEmpty())return;var p=players.get(Math.floorMod(playerCursor++,players.size()));var world=p.getServerWorld();var cp=p.getChunkPos();var loaded=world.getChunkManager().getWorldChunk(cp.x,cp.z);if(loaded==null)return;int examined=0;for(var ref:loaded.getStructureReferences().entrySet()){if(!supported(world,ref.getKey()))continue;for(long packed:ref.getValue()){if(++examined>32)return;var origin=new ChunkPos(packed);var chunk=world.getChunkManager().getWorldChunk(origin.x,origin.z);if(chunk==null)continue;var start=chunk.getStructureStart(ref.getKey());if(start!=null&&start.hasChildren())offer(world,start);}}}
 public static void step(MinecraftServer server){var jobs=JOBS.get(server);if(jobs==null||jobs.isEmpty())return;var entry=jobs.entrySet().iterator().next();var job=entry.getValue();var ledger=VillageBoardLedger.get(server);if(ledger.readOnly())return;if(server.getTicks()-job.lastTouched>Math.max(2400,server.getPlayerManager().getPlayerList().size()*200)){jobs.remove(entry.getKey());return;}boolean done=false;
  if(job.scanned.size()<job.chunks.size()){var cp=job.chunks.get(job.cursor++%job.chunks.size());var chunk=job.world.getChunkManager().getWorldChunk(cp.x,cp.z);if(chunk!=null&&!job.scanned.contains(cp.toLong())){boolean board=existingBoard(job.world,cp)!=null;if(board){ledger.record(job.key,"PLACED: existing board");done=true;}else job.scanned.add(cp.toLong());}}
  else {var cp=job.chunks.get(job.placement);if(job.world.getChunkManager().getWorldChunk(cp.x,cp.z)!=null){if(VillageNoticeBoards.attempt(job.world,cp)){ledger.record(job.key,"PLACED: "+cp);done=true;}else if(++job.placement==job.chunks.size()){ledger.record(job.key,"FAILED: no safe loaded surface; /wbboard repair remains available");com.witchersbestiary.WitchersBestiary.LOGGER.info("No safe notice board site for {}",job.key);done=true;}}}
  jobs.remove(entry.getKey());if(!done)jobs.put(entry.getKey(),job);
 }
 public static void initialize(){var path=net.fabricmc.loader.api.FabricLoader.getInstance().getConfigDir().resolve("witchersbestiary-village-boards.json");try{if(!java.nio.file.Files.exists(path))java.nio.file.Files.writeString(path,new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(java.util.Map.of("automaticVisitedVillages",true)));else enabled=com.google.gson.JsonParser.parseString(java.nio.file.Files.readString(path)).getAsJsonObject().get("automaticVisitedVillages").getAsBoolean();}catch(Exception e){enabled=false;com.witchersbestiary.WitchersBestiary.LOGGER.warn("Village board configuration invalid; visit repair disabled",e);}ServerTickEvents.END_SERVER_TICK.register(s->{if(enabled){if(s.getTicks()%100==0)discover(s);if(s.getTicks()%5==0)step(s);}});ServerLifecycleEvents.SERVER_STOPPED.register(s->JOBS.remove(s));}
}

